  const m = /^\[([^\]]+)\](?::(\d+))?$/.exec(target) || /^([^:]+)(?::(\d+))?$/.exec(target);
  return m ? { host: m[1].toLowerCase(), port: m[2] ? Number(m[2]) : null } : null;
